arguments.query:
SELECT parent_process_name, parent_process_path, parent_command_line, pname AS child_process_name, process_name AS child_process_path, command_line AS child_command_line
FROM audit_logs
WHERE pname = 'powershell.exe' AND parent_process_name IS NOT NULL AND parent_process_path IS NOT NULL AND parent_command_line IS NOT NULL;

